<template><div><h1>Add item</h1><AppInput v-model="name" placeholder="Name"/><AppButton @click="save">Save</AppButton></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {itemsApi,zonesApi} from '../api/client';import AppInput from '../components/AppInput.vue';import AppButton from '../components/AppButton.vue';const name=ref('');const router=useRouter();const save=async()=>{const zones=(await zonesApi.list()).data;await itemsApi.create({name:name.value,category:'OTHER',storageZoneId:zones[0].id,source:'MANUAL'});router.push('/inventory');};</script>
